<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Cable, Plus, RefreshCw, Trash2, Variable, Upload, Braces, Circle, Terminal, X, AlertCircle } from 'lucide-vue-next'
import FButton from './fluent/FButton.vue'
import { call, desktop, type Runtime } from '../lib/backend'
import { newId, type ConnectionConfig, type PluginManifest, type ValidationIssue } from '../lib/model'
import type { Editor } from '../lib/editor'
import { pluginCatalog } from '../lib/resources'
import SchemaField from './SchemaField.vue'
import { schemaDefaults } from '../lib/schema'
const props = defineProps<{ editor: Editor; runtime: Runtime; issues: ValidationIssue[]; expanded: boolean }>()
const emit = defineEmits<{ error: [message: string]; 'update:expanded': [value: boolean]; importPlugin: [] }>()
const tab = ref('connections'), selectedConnection = ref(''), ports = ref<{ name: string; description: string }[]>([]), plugins = pluginCatalog, runFilter = ref('')
const connection = computed(() => props.editor.project.value.connections.find(c => c.id === selectedConnection.value) ?? props.editor.project.value.connections[0])
const eventList = computed(() => props.runtime.events.value.filter(event => !runFilter.value || event.runId?.includes(runFilter.value)).slice(-300).reverse())
const protocol = computed(() => plugins.value.find(plugin => plugin.id === connection.value?.protocolId))
const configFields = computed(() => protocol.value?.configSchema?.properties ?? {})
const disabled = computed(() => props.editor.readOnly.value)
async function refresh() { if (!desktop) return; try { [ports.value, plugins.value] = await Promise.all([call<{ name: string; description: string }[]>('list_serial_ports'), call<PluginManifest[]>('list_plugins')]) } catch (error) { emit('error', String(error)) } }
onMounted(refresh)
function addConnection() { const item: ConnectionConfig = { id: newId('connection'), name: '新串口连接', port: '', baudRate: 115200, dataBits: 8, stopBits: 1, parity: 'none', protocolId: plugins.value[0]?.id ?? 'demo-temperature', protocolVersion: plugins.value[0]?.version ?? '1.0.0', protocolConfig: schemaDefaults(plugins.value[0]?.configSchema) }; props.editor.mutate(p => p.connections.push(item)); selectedConnection.value = item.id }
function editConnection(key: keyof ConnectionConfig, value: unknown) { if (connection.value) props.editor.mutate(() => { (connection.value as any)[key] = value; if (key === 'protocolId') { const plugin = plugins.value.find(p => p.id === value); connection.value!.protocolVersion = plugin?.version; connection.value!.protocolConfig = schemaDefaults(plugin?.configSchema) } }) }
function addVariable() { props.editor.mutate(p => p.variables.push({ id: newId('variable'), name: `变量 ${p.variables.length + 1}`, type: 'number', initial: 0 })) }
function variableValue(id: string, event: Event) { const variable = props.editor.project.value.variables.find(v => v.id === id)!; const value = (event.target as HTMLInputElement).value; props.editor.mutate(() => variable.initial = variable.type === 'number' ? Number(value) : variable.type === 'boolean' ? value === 'true' : value) }
function status(id: string) { const state = props.runtime.snapshot.value.connections[id]; if (!state) return '未连接'; const value = typeof state === 'string' ? state : state.status ?? state.state; return value === 'open' || value === 'connected' ? '已连接' : value === 'fault' || value === 'faulted' || value === 'error' ? '连接故障' : value === 'opening' ? '连接中' : value === 'closed' ? '已关闭' : String(value ?? '未连接') }
function showIssues() { tab.value = 'issues'; emit('update:expanded', true) }
defineExpose({ refresh, showIssues })
</script>

<template>
  <section class="resources-panel" :class="{ collapsed: !expanded }"><div class="resource-tabs"><button :class="{ active: tab === 'connections' }" @click="tab = 'connections'; emit('update:expanded', true)"><Cable :size="15" />设备连接<span>{{ editor.project.value.connections.length }}</span></button><button :class="{ active: tab === 'variables' }" @click="tab = 'variables'; emit('update:expanded', true)"><Variable :size="15" />项目变量<span>{{ editor.project.value.variables.length }}</span></button><button :class="{ active: tab === 'events' }" @click="tab = 'events'; emit('update:expanded', true)"><Terminal :size="15" />执行记录<span>{{ runtime.events.value.length }}</span></button><button :class="{ active: tab === 'issues' }" @click="showIssues"><AlertCircle :size="15" />检查<span :class="{ 'error-count': issues.some(i => i.severity === 'error') }">{{ issues.length }}</span></button><span class="spacer" /><button class="icon-button" :title="expanded ? '收起面板' : '展开面板'" @click="emit('update:expanded', !expanded)"><X v-if="expanded" :size="14" /><Plus v-else :size="14" /></button></div>
    <div v-if="expanded && tab === 'connections'" class="connections-content"><div class="connection-list"><div class="inline-between"><span class="small muted">串口资源</span><button class="icon-button" title="添加串口连接" :disabled="disabled" @click="addConnection"><Plus :size="15" /></button></div><button v-for="item in editor.project.value.connections" :key="item.id" class="connection-item" :class="{ active: connection?.id === item.id }" @click="selectedConnection = item.id"><Cable :size="17" /><span><strong>{{ item.name }}</strong><small>{{ item.port || '尚未配置端口' }}</small></span><i :class="{ connected: status(item.id) === '已连接' }" /></button><div v-if="!editor.project.value.connections.length" class="small muted">添加串口资源后，在流程中配置打开连接。</div></div><div v-if="connection" class="connection-settings"><div class="inline-between connection-heading"><strong>{{ connection.name }}</strong><span class="status-pill">{{ status(connection.id) }}</span><span class="spacer" /><button class="text-button" :disabled="disabled" @click="emit('importPlugin')"><Upload :size="13" />导入协议</button><button class="icon-button" title="刷新端口与插件" @click="refresh"><RefreshCw :size="14" /></button><button class="icon-button" title="删除连接资源" :disabled="disabled" @click="editor.mutate(p => p.connections = p.connections.filter(c => c.id !== connection!.id))"><Trash2 :size="14" /></button></div><fieldset :disabled="disabled" class="connection-grid"><label>资源名称<input :value="connection.name" @change="editConnection('name', ($event.target as HTMLInputElement).value)" /></label><label>串口<select :value="connection.port" @change="editConnection('port', ($event.target as HTMLSelectElement).value)"><option value="">选择串口</option><option value="sim://temperature">示例模拟设备</option><option v-if="connection.port && connection.port !== 'sim://temperature' && !ports.some(p => p.name === connection!.port)" :value="connection.port">{{ connection.port }}（当前不可用）</option><option v-for="port in ports" :key="port.name" :value="port.name">{{ port.name }} {{ port.description }}</option></select></label><label>波特率<select :value="connection.baudRate" @change="editConnection('baudRate', Number(($event.target as HTMLSelectElement).value))"><option v-for="rate in [1200,2400,4800,9600,19200,38400,57600,115200,230400,460800,921600]" :key="rate" :value="rate">{{ rate }}</option></select></label><label>数据位<select :value="connection.dataBits" @change="editConnection('dataBits', Number(($event.target as HTMLSelectElement).value))"><option v-for="bits in [5,6,7,8]" :key="bits">{{ bits }}</option></select></label><label>停止位<select :value="connection.stopBits" @change="editConnection('stopBits', Number(($event.target as HTMLSelectElement).value))"><option>1</option><option>2</option></select></label><label>校验<select :value="connection.parity" @change="editConnection('parity', ($event.target as HTMLSelectElement).value)"><option value="none">无</option><option value="odd">奇校验</option><option value="even">偶校验</option></select></label><label>协议插件<select :value="connection.protocolId" @change="editConnection('protocolId', ($event.target as HTMLSelectElement).value)"><option v-if="!plugins.some(p => p.id === connection!.protocolId)" :value="connection.protocolId">{{ connection.protocolId }}</option><option v-for="plugin in plugins" :key="plugin.id" :value="plugin.id">{{ plugin.name }} · {{ plugin.version }}</option></select></label><SchemaField v-for="(schema, key) in configFields" :key="`${connection.id}:${key}`" :schema="schema as any" :label="(schema as any).title ?? String(key)" :model-value="connection.protocolConfig[key]" @update:model-value="value => editor.mutate(() => connection!.protocolConfig[key] = value)" /></fieldset><div class="connection-foot"><span v-if="connection.port.startsWith('sim://')" class="muted small">当前使用示例模拟设备，可切换为实际设备串口。</span><span v-else class="muted small">串口在预览运行时由连接节点打开。</span><span class="spacer" /><FButton v-if="runtime.running.value" @click="call(status(connection.id) === '已连接' ? 'close_connection' : 'open_connection', { connectionId: connection.id, expectedGeneration: runtime.generation.value }).then(runtime.refresh).catch(error => emit('error', String(error)))">{{ status(connection.id) === '已连接' ? '关闭连接' : '打开连接' }}</FButton></div></div><div v-else class="resources-empty"><Cable :size="28" /><span>添加串口连接，配置设备参数</span></div></div>
    <div v-else-if="expanded && tab === 'variables'" class="variables-content"><div class="inline-between"><span class="muted small">变量用于在流程与界面间共享数据，重启后恢复初始值。</span><FButton :disabled="disabled" @click="addVariable"><Plus :size="14" />添加变量</FButton></div><table><thead><tr><th>名称</th><th>标识</th><th>类型</th><th>初始值</th><th>运行值</th><th /></tr></thead><tbody><tr v-for="variable in editor.project.value.variables" :key="variable.id"><td><input :value="variable.name" :disabled="disabled" @change="editor.mutate(() => variable.name = ($event.target as HTMLInputElement).value)" /></td><td><code>{{ variable.id }}</code></td><td><select :value="variable.type" :disabled="disabled" @change="editor.mutate(() => { variable.type = ($event.target as HTMLSelectElement).value as any; variable.initial = variable.type === 'number' ? 0 : variable.type === 'boolean' ? false : variable.type === 'enum' ? '选项一' : ''; if (variable.type === 'enum') variable.options = ['选项一', '选项二'] })"><option value="number">数字</option><option value="string">文本</option><option value="boolean">布尔</option><option value="enum">枚举</option></select></td><td><select v-if="variable.type === 'boolean'" :value="String(variable.initial)" :disabled="disabled" @change="variableValue(variable.id, $event)"><option value="false">false</option><option value="true">true</option></select><template v-else-if="variable.type === 'enum'"><select :value="variable.initial" :disabled="disabled" @change="variableValue(variable.id, $event)"><option v-for="option in variable.options ?? []" :key="option" :value="option">{{ option }}</option></select><input :value="variable.options?.join(', ')" placeholder="枚举选项，用逗号分隔" :disabled="disabled" @change="editor.mutate(() => { variable.options = ($event.target as HTMLInputElement).value.split(/[,，]/).map(value => value.trim()).filter(Boolean); if (!variable.options.includes(String(variable.initial))) variable.initial = variable.options[0] ?? '' })" /></template><input v-else :value="variable.initial" :type="variable.type === 'number' ? 'number' : 'text'" :disabled="disabled" @change="variableValue(variable.id, $event)" /></td><td><code>{{ JSON.stringify(runtime.snapshot.value.variables[variable.id] ?? '—') }}</code></td><td><button class="icon-button" title="删除变量" :disabled="disabled" @click="editor.mutate(p => p.variables = p.variables.filter(v => v.id !== variable.id))"><Trash2 :size="14" /></button></td></tr></tbody></table></div>
    <div v-else-if="expanded && tab === 'events'" class="events-content"><div class="inline-between"><input v-model="runFilter" class="run-filter" placeholder="按运行 ID 筛选…" aria-label="筛选运行记录" /><span class="muted small">{{ runtime.running.value ? '记录中' : '尚未运行或已停止' }}</span><button class="text-button" @click="runtime.events.value = []">清空</button></div><div class="event-table"><div v-if="!eventList.length" class="resources-empty"><Terminal :size="25" /><span>进入预览并触发流程后，在此查看执行路径与结果。</span></div><details v-for="(event, index) in eventList" :key="`${event.runId}-${event.nodeId}-${index}`" class="event-row" :class="{ failed: event.kind.endsWith('failed') }"><summary><time>{{ new Date(event.timestamp).toLocaleTimeString('zh-CN') }}</time><span>{{ event.kind }}</span><code>{{ event.runId?.slice(-8) ?? '—' }}</code><span>{{ editor.project.value.flows.flatMap(f => f.nodes).find(n => n.id === event.nodeId)?.label ?? event.flowId ?? '' }}</span><span class="event-preview">{{ JSON.stringify(event.data) }}</span></summary><pre>{{ JSON.stringify(event.data, null, 2) }}</pre></details></div></div>
    <div v-else-if="expanded" class="issues-content"><div v-if="!issues.length" class="resources-empty"><Circle :size="24" /><span>暂无检查结果。点击顶部「检查」验证项目。</span></div><div v-for="(issue, index) in issues" :key="index" class="issue-row"><AlertCircle :size="16" :class="issue.severity === 'error' ? 'error-copy' : 'muted'" /><code>{{ issue.path }}</code><span>{{ issue.message }}</span></div></div>
  </section>
</template>
